    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if any(v == 2 for v in grid[r])]
    if rows:
        top, bottom = min(rows), max(rows)
        for r in range(top, bottom + 1):
            if not any(v == 2 for v in grid[r]):
                out[r] = [3] * w
    return out
